using Kernel = typename Tree::Traits::Kernel;
using Ray = CGAL::Ray_3<Kernel>;

std::mt19937 gen(std::random_device{}());
std::normal_distribution<double> nd(0.0, 1.0);
int insideVotes = 0;

for (int i = 0; i < numberOfChecks; ++i) {
    double dx = nd(gen);
    double dy = nd(gen);
    double dz = nd(gen);
    double len = std::sqrt(dx * dx + dy * dy + dz * dz);
    if (len == 0.0) {
        --i; // retry this iteration
        continue;
    }
    dx /= len; dy /= len; dz /= len;

    Point3d farPoint(p.x() + dx, p.y() + dy, p.z() + dz);
    Ray ray(p, farPoint);

    std::size_t hits = tree.number_of_intersections(ray);
    if (hits % 2 == 1) {
        ++insideVotes;
    }
}

return insideVotes > numberOfChecks / 2;

